import{_ as d,C as a,o as h,c as u,j as t,a as r,G as s,a2 as n}from"./chunks/framework.BgSoyxN5.js";const P=JSON.parse('{"title":"TickerForge Partners | Research, Market News, and Telegram Tools","description":"Partner with TickerForge through Telegram research blocks, automated market intelligence posts, portfolio diagnostics, tracked links, and measurable pilot campaigns.","frontmatter":{"title":"TickerForge Partners | Research, Market News, and Telegram Tools","description":"Partner with TickerForge through Telegram research blocks, automated market intelligence posts, portfolio diagnostics, tracked links, and measurable pilot campaigns.","aside":false,"locale":"en","alternateLocales":{"en":"/partners","ru":"/ru/partners"},"pageClass":"partners-page partner-hub-page"},"headers":[],"relativePath":"partners.md","filePath":"partners.md","lastUpdated":1789293971000}'),g={name:"partners.md"},m={class:"partners-wide"};function f(w,e,b,k,y,v){const o=a("PartnerPageAnalytics"),i=a("PartnerChannelCta"),l=a("PartnerCabinetCta"),p=a("PartnerReferralCta"),c=a("PartnerLeadForm");return h(),u("div",null,[e[0]||(e[0]=t("h1",{id:"partner-with-tickerforge",tabindex:"-1"},[r("Partner with TickerForge "),t("a",{class:"header-anchor",href:"#partner-with-tickerforge","aria-label":'Permalink to "Partner with TickerForge"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Research tools, automated market intelligence, and portfolio diagnostics for finance creators — on Telegram, Instagram, YouTube, TikTok, LinkedIn, a newsletter, or a site of your own.",-1)),e[2]||(e[2]=t("p",null,"TickerForge helps creators and communities add structured market context, stock diagnostics, portfolio health checks, and automated research posts without building their own fintech product. If you publish about markets anywhere and your audience trusts you enough to click, this program is for you — the platform is not the qualifier.",-1)),e[3]||(e[3]=t("p",null,[r("Start with "),t("strong",null,"14 days of Standard Review Access"),r(", after application review. No publications required. If it fits, agree a "),t("strong",null,"Pilot with 1–2 test posts"),r(", supported by research blocks and tracked links. After a successful pilot, discuss "),t("strong",null,"Active Partner"),r(" terms: for example 2–4 posts per month, referral, paid or co-branded content.")],-1)),s(o,{offer:"hub",locale:"en"}),e[4]||(e[4]=t("div",{class:"partners-hero-actions"},[t("a",{class:"partners-button partners-button--primary",href:"#partner-contact"},"Request 14-day Review Access"),t("a",{class:"partners-button partners-button--secondary",href:"#partner-options"},"Explore Partner Options")],-1)),s(i),e[5]||(e[5]=n('<p class="partners-locale-switch"><a href="/ru/partners" hreflang="ru" data-partner-event="cta" data-partner-option="locale_ru" data-analytics-placement="partner_locale_switch">Читать эту страницу на русском</a></p><div class="partners-wide partners-routing-note"><p><strong>Looking for a specific format?</strong> Each direction has its own page with the content formats it covers: company research, market and macro content, or portfolio diagnostics.</p><a class="partners-button partners-button--secondary" href="#partner-options">See partner options</a></div><p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, or a promise of investment results.</p><h2 id="partner-options" tabindex="-1">Partner Options <a class="header-anchor" href="#partner-options" aria-label="Permalink to &quot;Partner Options {#partner-options}&quot;">​</a></h2><p>Two things shape a pilot: <strong>where</strong> you publish, and <strong>what</strong> you publish. Start with where — the two groups below work differently enough that the pilot itself has a different shape.</p><h3 id="for-telegram-and-web" tabindex="-1">1 · Telegram and web creators <a class="header-anchor" href="#for-telegram-and-web" aria-label="Permalink to &quot;1 · Telegram and web creators {#for-telegram-and-web}&quot;">​</a></h3><p>Your audience reads posts: a Telegram channel, a community, a newsletter, a blog. TickerForge generates the finished post — text, channel image, your own tracked link inside it — and you publish it in your own voice. Pick the direction that matches what you already write about.</p><div class="partners-wide"><div class="partners-option-grid"><a class="partners-option" href="/partners/stock-analysis-and-ideas" data-partner-event="option" data-partner-option="telegram_research" data-analytics-placement="partner_hub_options"><span>Research layer</span><strong>Stock Analysis &amp; Ideas Layer</strong><p>Add TickerForge evidence blocks to your own posts: Stock Verdict, Insider Activity, Fund Moves, and Stock Ideas.</p><p><strong>Best for:</strong></p><ul class="partners-option-best"><li>Telegram finance channels</li><li>stock analysis creators</li><li>communities discussing tickers</li><li>creators who want stronger research posts</li></ul><span class="partners-option-cta">Open page</span></a><a class="partners-option" href="/partners/market-news" data-partner-event="option" data-partner-option="market_news" data-analytics-placement="partner_hub_options"><span>Recurring content</span><strong>Automated Market News</strong><p>Use TickerForge daily and weekly market intelligence posts as recurring channel content.</p><p><strong>Best for:</strong></p><ul class="partners-option-best"><li>finance channels that need consistent market updates</li><li>communities that want daily or weekly risk context</li><li>creators who want market regime, stress, and sector rotation summaries</li></ul><span class="partners-option-cta">Open page</span></a><a class="partners-option" href="/partners/portfolio-health" data-partner-event="option" data-partner-option="portfolio_health" data-analytics-placement="partner_hub_options"><span>Portfolio diagnostics</span><strong>Portfolio Health</strong><p>Let your audience check concentration, sector exposure, cash buffer, and stress-test risk on their own holdings.</p><p><strong>Best for:</strong></p><ul class="partners-option-best"><li>portfolio-focused creators</li><li>consultants</li><li>communities with investor portfolios</li><li>co-branded or white-label discussions</li></ul><span class="partners-option-cta">Open page</span></a></div></div><p>Each page lists the content formats in that direction, and the form at the bottom of this page takes the same choice: one program, plus whichever formats interest you.</p><h3 id="for-video" tabindex="-1">2 · YouTube, Instagram and TikTok creators <a class="header-anchor" href="#for-video" aria-label="Permalink to &quot;2 · YouTube, Instagram and TikTok creators {#for-video}&quot;">​</a></h3><p>Your audience watches. A generated post is not something you can forward into a video, so the pilot works the other way round: TickerForge becomes one research layer <em>inside</em> the format your audience already knows. You show a real check on screen, keep your own analysis and conclusion, and put a tracked link in the description, the bio or a pinned comment. The subject is still one of the three directions above — what changes is how it reaches people.</p><div class="partners-wide partners-cta-panel"><span>Video, Reels, Shorts, LinkedIn, newsletters</span><strong>Creator Partnerships</strong><p>One qualified content test, agreed creator access for the pilot window, and a tracked link you own.</p><a class="partners-button partners-button--primary" href="/partners/creators" data-partner-event="option" data-partner-option="creators" data-analytics-placement="partner_hub_options">Explore creator partnerships</a></div>',12)),s(l,{locale:"en"}),e[6]||(e[6]=n('<h2 id="partner-access" tabindex="-1">🎁 Partner Benefits <a class="header-anchor" href="#partner-access" aria-label="Permalink to &quot;🎁 Partner Benefits {#partner-access}&quot;">​</a></h2><p>Approved applicants start with 14 days of Standard Review Access, with no publications required. Any later Pilot has its own agreed access window. This applies beyond Telegram: a LinkedIn group owner, YouTube creator, Instagram finance blogger, newsletter author, or community operator can use the product to prepare better posts and route interested readers through tracked links.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>⭐ Standard access.</strong> 14 days of Standard Review Access with no publications required; then Standard for an agreed Pilot window.</li><li><strong>🧰 Partner Cabinet.</strong> Your own workspace inside the bot: pick a format, press one button, get a finished post with your link already in it. Post language, statistics and the monthly report live there too. <a href="/partners/cabinet">How it works</a>.</li><li><strong>🧠 Ready-to-post content.</strong> Not raw data to write around — a finished post, on live data, in the shape your format needs. Stock Verdict, Insider Activity, Fund Moves, weekly stock ideas, Market Regime and U.S. Economic Health, generated on demand.</li><li><strong>🔗 Tracked links.</strong> Every partner post carries your own link inside its call to action, and it sends readers straight into the matching TickerForge workflow.</li><li><strong>💰 Referral earnings.</strong> Up to <strong>20% every month</strong> of what the people who came from you pay, for as long as they stay subscribed — the same rules as <a href="/ambassador">/ambassador</a>. No cap on referrals or on monthly rewards.</li><li><strong>📊 Measurable results.</strong> Generated posts, bot starts per format, referrals, and estimated earnings in your Partner Cabinet.</li></ul></div><h2 id="formats" tabindex="-1">Formats You Can Publish In <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Formats You Can Publish In {#formats}&quot;">​</a></h2><p>For creators using their own video, carousel, article, or newsletter format, see <a href="/partners/creators">Creator Partnerships</a>. No generated-post integration is required for that pilot.</p><p>The Partner Cabinet generates a post as text plus your own tracked link. That is the container Telegram needs — and the same generated post, with the same link, is what the other containers are built on. Tell us which one you need and it moves up the queue.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Available today</span><strong>Telegram post</strong><p>Formatted text with the channel image and your tracked link inside it. Generated in one tap, forwarded as it arrives.</p></div><div class="partners-format"><span>On request for a pilot</span><strong>Web page post</strong><p>The same generated post as a block for your own site, blog or newsletter platform, with the link pointing at the web workflow instead of the bot.</p></div><div class="partners-format"><span>On request for a pilot</span><strong>Web widget</strong><p>An embeddable live view that updates itself, rather than a post you republish every week.</p></div><div class="partners-format"><span>Expected</span><strong>Email</strong><p>The same post shaped for a newsletter send, so a creator who publishes by email is not forced into a chat app.</p></div><div class="partners-format"><span>Expected</span><strong>RSS feed</strong><p>A feed your own automation can consume and place wherever your audience already reads you.</p></div></div></div><p>Anything not on this list is worth asking for. The list is what exists and what is queued, not the limit of what the generated post can be poured into.</p><h2 id="partner-requirements" tabindex="-1">What We Ask In Return <a class="header-anchor" href="#partner-requirements" aria-label="Permalink to &quot;What We Ask In Return {#partner-requirements}&quot;">​</a></h2><p>Review Access carries no publishing commitment. If you want to continue, we agree a Pilot first; regular collaboration is discussed only after that test.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Audience:</strong> from 1,000 real subscribers on the channel you post in, in a finance or investing topic. Smaller but strongly engaged communities are considered case by case.</li><li><strong>Review Access:</strong> 14 days of Standard, no publications required. <strong>Pilot:</strong> 1–2 agreed test posts with research blocks and tracked links.</li><li><strong>Qualified post:</strong> a real TickerForge check, your own voice, a clear educational disclaimer, and a tracked link. Only published posts we can verify count.</li><li><strong>Disclosure:</strong> sponsored, affiliate-supported, or complimentary-access-supported content is disclosed by the partner.</li><li><strong>Personal seat:</strong> access is approved case by case, time-limited, and non-transferable. Publishing commitments apply only after a Pilot or ongoing collaboration is agreed.</li></ul></div><div class="partners-wide partners-routing-note"><p><strong>Full eligibility rules, commitments, and the exact conditions under which access ends</strong> are on a separate page, so this one stays readable.</p><a class="partners-button partners-button--secondary" href="/partners/what-you-get" data-partner-event="cta" data-partner-option="what_you_get" data-analytics-placement="partner_hub_what_you_get">What You Get</a><a class="partners-button partners-button--secondary" href="/partners/requirements" data-partner-event="cta" data-partner-option="requirements" data-analytics-placement="partner_hub_requirements">Open Partner Requirements</a></div><p>Pro access, bulk API, custom feeds, co-branded reports, and white-label workflows are not part of a pilot — they are separate commercial discussions.</p><h2 id="three-stages-of-partnership" tabindex="-1">Three Stages Of Partnership <a class="header-anchor" href="#three-stages-of-partnership" aria-label="Permalink to &quot;Three Stages Of Partnership&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps partners-steps--three"><div><span>1</span><strong>Review Access</strong><p>14 days of Standard after application review. Explore the product, data and post formats. No publications required.</p></div><div><span>2</span><strong>Pilot</strong><p>If it fits, agree 1–2 test posts and a separate access window. We provide a ready research block and tracked links.</p></div><div><span>3</span><strong>Active Partner</strong><p>After a successful pilot, discuss regular collaboration: for example 2–4 posts per month, referral, paid or co-branded content.</p></div></div></div>',15)),s(p),e[7]||(e[7]=n('<h2 id="what-tickerforge-is-not" tabindex="-1">What TickerForge Is Not <a class="header-anchor" href="#what-tickerforge-is-not" aria-label="Permalink to &quot;What TickerForge Is Not&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>TickerForge is not:</p><ul><li>a trading robot</li><li>a signal channel</li><li>a broker</li><li>a copy-trading system</li><li>a promise of profit</li><li>personalized financial advice</li></ul><p>TickerForge is educational decision-support software for reviewing stock, portfolio, ownership, and market context before acting.</p></div><h2 id="partner-contact" tabindex="-1">Request 14-day Review Access <a class="header-anchor" href="#partner-contact" aria-label="Permalink to &quot;Request 14-day Review Access {#partner-contact}&quot;">​</a></h2><p>Tell us about your channel, audience and what you want to explore during Review Access. A publishing commitment is not required; we can discuss a Pilot after you have tried the product.</p>',4)),t("div",m,[s(c,{source:"partners_hub"})]),e[8]||(e[8]=n('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/partners/creators">Creator partnerships</a></li><li><a href="/partners/what-you-get">What we give a partner</a></li><li><a href="/partners/requirements">Partner requirements</a></li><li><a href="/partners/cabinet">How Partner Cabinet works</a></li><li><a href="/partners/stock-analysis-and-ideas">Stock Analysis &amp; Ideas partners</a></li><li><a href="/partners/market-news">Market news partners</a></li><li><a href="/partners/portfolio-health">Portfolio health partners</a></li><li><a href="/import-portfolio">Portfolio Health Check</a></li><li><a href="/stock-widget">Stock Check Widget</a></li><li><a href="/market-widget">Market Regime Widget</a></li><li><a href="/ambassador">Ambassador / referral program</a></li><li><a href="/pricing">TickerForge Pricing</a></li></ul>',2))])}const _=d(g,[["render",f]]);export{P as __pageData,_ as default};
